mkdir -p \.
echo '' | base64 -d > 'src/config.js'
echo 'Writing src/data/binanceClient.js'...
mkdir -p \.
echo '' | base64 -d > 'src/data/binanceClient.js'
echo 'Writing src/data/mockData.js'...
mkdir -p \.
echo '' | base64 -d > 'src/data/mockData.js'
echo 'Writing src/smc/smcAnalyzer.js'...
