echo '' | base64 -d > 'src/smart_money/smartMoneyAnalyzer.js'
echo 'Writing src/technical/technicalAnalyzer.js'...
mkdir -p \.
echo '' | base64 -d > 'src/technical/technicalAnalyzer.js'
echo 'Writing src/brain/thesisEngine.js'...
mkdir -p \.
echo '' | base64 -d > 'src/brain/thesisEngine.js'
echo 'Writing src/brain/memory.js'...
mkdir -p \.
echo '' | base64 -d > 'src/brain/memory.js'
echo 'Writing src/brain/riskAnalysis.js'...
